os.makedirs("data", exist_ok=True)

# 1. Remove old cached FAISS indexes so it rebuilds cleanly
for old_file in ["data/faiss.index", "data/metadata.json", "data/ipc_faiss.index", "data/ipc_metadata.json"]:
    if os.path.exists(old_file):
        os.remove(old_file)
        print(f"Removed old cache: {old_file}")

# 2. Write the new 20 everyday law records
with open("data/legal_data.jsonl", "w", encoding="utf-8") as f:
    for r in RECORDS:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

print("Successfully updated data/legal_data.jsonl with 20 structured records!")